script:
macroScript DigitalTwinCleanup
category:"3DFlowHub"
tooltip:"디지털 트윈 씬 정리"
(
	fn cleanSceneObjects = (
		local allObjs = objects as array
		for obj in allObjs do (
			if superclassof obj == GeometryClass then (
				select obj
				resetTransform obj
				collapseStack obj
			)
		)
		deletetag = undefined
		messageBox "디지털 트윈 오브젝트 정리가 완료되었습니다." title:"완료"
	)

	on execute do (
		undo "Digital Twin Cleanup" on
		(
			cleanSceneObjects()
		)
	)
)
